// TypeScript Version: 4.1

/// <reference types="@stdlib/types"/>

/**
* Interface describing `dlasrt`.
*/
interface Routine {
	/**
	* Sorts an array of doubles in increasing or decreasing order using quicksort, with insertion sort for small partitions (size <= 20).
	*
	*
	* @param ID - sort direction: 'Increasing' or 'Decreasing'
	* @param N - number of elements to sort
	* @param D - array to sort in-place
	* @returns status code (0 = success, -i = the i-th argument had an illegal value)
	*
	* @example
	* var Float64Array = require( '@stdlib/array/float64' );
	*
	* var D = new Float64Array( [ 5, 7, 9, 3, 11 ] );
	*
	* dlasrt( 'Increasing', 5, D );
	* // D => <Float64Array>[ 3, 5, 7, 9, 11 ]
	*/
	( ID: string, N: number, D: Float64Array ): number;

	/**
	* Sort an array of doubles in increasing or decreasing order using quicksort, with insertion sort for small partitions (size <= 20) using alternative indexing semantics.
	*
	* @param ID - sort direction: 'Increasing' or 'Decreasing'
	* @param N - number of elements to sort
	* @param D - array to sort in-place
	* @param strideD - stride length for `d`
	* @param offsetD - starting index for `d`
	* @returns status code (0 = success, -i = the i-th argument had an illegal value)
	*
	* @example
	* var Float64Array = require( '@stdlib/array/float64' );
	*
	* var D = new Float64Array( [ 5, 7, 9, 3, 11 ] );
	*
	* dlasrt( 'Increasing', 5, D, 1, 0 );
	* // D => <Float64Array>[ 3, 5, 7, 9, 11 ]
	*/
	ndarray( ID: string, N: number, D: Float64Array, strideD: number, offsetD: number ): number;
}

/**
* LAPACK routine to sort an array of doubles in increasing or decreasing order using quicksort, with insertion sort for small partitions (size <= 20).
*
*
* @param ID - sort direction: 'Increasing' or 'Decreasing'
* @param N - number of elements to sort
* @param D - array to sort in-place
* @returns status code (0 = success, -i = the i-th argument had an illegal value)
*
* @example
* var Float64Array = require( '@stdlib/array/float64' );
*
* var D = new Float64Array( [ 5, 7, 9, 3, 11 ] );
*
* dlasrt( 'Increasing', 5, D );
* // D => <Float64Array>[ 3, 5, 7, 9, 11 ]
*
* @example
* var Float64Array = require( '@stdlib/array/float64' );
*
* var D = new Float64Array( [ 5, 7, 9, 3, 11 ] );
*
* dlasrt( 'Increasing', 5, D, 1, 0 );
* // D => <Float64Array>[ 3, 5, 7, 9, 11 ]
*/
declare var dlasrt: Routine;


// EXPORTS //

export = dlasrt;
